  roofline:['Berkeley Lab · the Roofline performance model','https://amcr.lbl.gov/departments/computer-science-department/ppan/roofline-performance-model/'],
  amdahl:['Robert G. Brown · Amdahl’s law and parallel speedup','https://static.usenix.org/publications/library/proceedings/als00/2000papers/papers/full_papers/brownrobert/brownrobert_html/node3.html'],
  load:['Gil Tene · wrk2 and coordinated omission','https://github.com/giltene/wrk2'],
  gc:['Go · a guide to garbage collection','https://go.dev/doc/gc-guide'],
  processes:['OSTEP · the process abstraction','https://pages.cs.wisc.edu/~remzi/OSTEP/cpu-intro.pdf'],
